function miniLine(values,label,axisLabels=['Início','30 dias','60 dias','90 dias']){const clean=values.filter(Number.isFinite);if(clean.length<2)return '<div class="empty-inline">O gráfico aparecerá com mais dados.</div>';const w=360,h=96,pad=12,min=Math.min(...clean,0),max=Math.max(...clean,0),range=max-min||1,points=clean.map((v,i)=>`${pad+i*(w-2*pad)/(clean.length-1)},${h-pad-(v-min)*(h-2*pad)/range}`).join(' '),zeroY=h-pad-(0-min)*(h-2*pad)/range;return `<div class="visual-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><line x1="${pad}" y1="${zeroY}" x2="${w-pad}" y2="${zeroY}" class="chart-zero"/><polyline points="${points}" class="chart-line"/><circle cx="${w-pad}" cy="${h-pad-(clean[clean.length-1]-min)*(h-2*pad)/range}" r="4" class="chart-point"/></svg><div class="visual-chart-labels">${axisLabels.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div>`}
function cashProjection(days){const cents=db.prefs.balanceAnchorCents,anchor=db.prefs.balanceAnchorDate,today=isoToday();if(!Number.isSafeInteger(cents)||!validDate(anchor)||anchor>today)return null;let balance=cents;for(const r of db.records)if(r.date>anchor&&r.date<=today)balance+=r.kind==='income'?r.amount:-r.amount;for(const a of db.allocations)if(a.date>anchor&&a.date<=today)balance+=a.netReceived??-a.amount;const investmentEvents=Engines.investmentCashEvents(db);for(const item of investmentEvents)if(item.date>anchor&&item.date<=today)balance+=item.amount;const nowBalance=balance,end=shiftIso(today,days),events=investmentEvents.filter(item=>item.date>today&&item.date<=end);for(const r of db.records)if(r.date>today&&r.date<=end)events.push({date:r.date,amount:r.kind==='income'?r.amount:-r.amount});for(const a of db.allocations)if(a.date>today&&a.date<=end)events.push({date:a.date,amount:a.netReceived??-a.amount});const last=new Date(end+'T12:00:00');for(const t of db.recurring.filter(x=>!x.paused)){for(let i=0;i<=3;i++){const monthDate=new Date(new Date(today+'T12:00:00').getFullYear(),new Date(today+'T12:00:00').getMonth()+i,1),key=mkey(monthDate.getFullYear(),monthDate.getMonth());if(key<t.startMonth||t.endMonth&&key>t.endMonth)continue;const day=Math.min(t.day,new Date(monthDate.getFullYear(),monthDate.getMonth()+1,0).getDate()),date=key+'-'+String(day).padStart(2,'0');if(date<=today||date>end)continue;if(db.records.some(r=>r.recurringId===t.id&&(r.recurringMonth||r.date.slice(0,7))===key))continue;events.push({date,amount:t.kind==='income'?t.amount:-t.amount})}}events.sort((a,b)=>a.date.localeCompare(b.date));let running=nowBalance,lowest=running;for(const e of events){running+=e.amount;lowest=Math.min(lowest,running)}return{days,end,nowBalance,projected:running,lowest,events:events.length}}
function cashflowCard(){const horizons=[30,60,90].map(n=>cashProjection(n));if(horizons.every(x=>x===null))return `<article class="card">${cardTitle('Previsão de caixa em 30, 60 e 90 dias','Inclui contas recorrentes e lançamentos futuros informados.')}<div class="empty"><strong>Informe seu saldo disponível de referência</strong>Em Ajustes, registre o saldo atual e a data a que ele corresponde. A projeção usa esse valor e os lançamentos feitos depois dessa data.<button class="btn" data-page="settings" style="margin-top:12px">Configurar saldo</button></div></article>`;return `<article class="card">${cardTitle('Previsão de caixa em 30, 60 e 90 dias','Saldo inicial informado por você, com recorrências e lançamentos futuros conhecidos.')}${miniLine([horizons[0]?.nowBalance,horizons[0]?.projected,horizons[1]?.projected,horizons[2]?.projected],'Linha do saldo projetado em 30, 60 e 90 dias')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Prazo</th><th>Data</th><th>Saldo previsto</th><th>Menor saldo no período</th><th>Eventos</th></tr></thead><tbody>${horizons.map(x=>`<tr><td>${x.days} dias</td><td>${dateBR(x.end)}</td><td class="money ${x.projected<0?'danger-text':''}">${money(x.projected)}</td><td class="money ${x.lowest<0?'danger-text':''}">${money(x.lowest)}</td><td>${x.events}</td></tr>`).join('')}</tbody></table></div><p class="help">Projeção informativa: depende do saldo de referência, da atualização dos registros e das contas recorrentes cadastradas. Não inclui transações que ainda não foram registradas ou previstas.</p></article>`}
function emergencyReserveCard(){const now=new Date(),periods=[-3,-2,-1].map(delta=>{const d=new Date(now.getFullYear(),now.getMonth()+delta,1);return mkey(d.getFullYear(),d.getMonth())}),samples=periods.map(key=>({key,expense:sum(db.records.filter(r=>r.kind==='expense'&&r.date.startsWith(key)).map(r=>r.amount))})).filter(x=>x.expense>0),average=samples.length?Math.round(sum(samples.map(x=>x.expense))/samples.length):0,months=db.prefs.emergencyMonths||6,target=average*months,reserve=sum(db.jars.filter(j=>!j.archived).map(j=>estimateCdbJar(j.id).net)),cover=average?reserve/average:null,remaining=Math.max(0,target-reserve);if(!average||!db.jars.some(j=>!j.archived))return '';return `<article class="card">${cardTitle('Reserva de emergência','Compara os CDBs registrados com a média das despesas dos meses fechados recentes.')}<div class="prediction-grid"><div><span>Média mensal de despesas</span><strong>${average?money(average):'—'}</strong></div><div><span>Reserva líquida estimada</span><strong>${money(reserve)}</strong></div><div><span>Meses cobertos</span><strong>${cover===null?'Histórico insuficiente':cover.toFixed(1).replace('.',',')}</strong></div></div><div class="reserve-meter"><div class="reserve-meter-fill" style="width:${target?Math.min(100,reserve/target*100):0}%"></div></div><p class="help">Referência configurada: ${months} meses · meta sugerida ${average?money(target):'aguardando despesas'} · faltam ${money(remaining)}. Usa todas as despesas registradas, sem classificar apenas as essenciais. Pressupõe que os CDBs possam ser resgatados quando necessário.</p></article>`}
function guaranteeCard(){const groups=new Map();for(const i of db.institutions){if(!['fgc','fgcoop'].includes(i.guaranteeFund))continue;const key=i.guaranteeFund+'|'+(i.conglomerate||i.name).trim().toLocaleLowerCase('pt-BR');if(!groups.has(key))groups.set(key,{fund:i.guaranteeFund,name:i.conglomerate||i.name,total:0});const g=groups.get(key);g.total+=i.otherCoveredBalance||0;for(const j of db.jars.filter(j=>!j.archived&&j.institutionId===i.id))g.total+=estimateCdbJar(j.id).gross}const cap=25000000,rows=[...groups.values()];return `<article class="card">${cardTitle('Monitoramento FGC e FGCoop','Exposição estimada informada por você, agrupada por fundo e conglomerado.')}<div class="institution-list">${rows.length?rows.map(g=>`<div class="institution-row"><span><b>${fundLabel(g.fund)} · ${esc(g.name)}</b><small>Exposição cadastrada: ${money(g.total)} · margem até a referência de R$ 250 mil: ${money(Math.max(0,cap-g.total))}</small><span class="reserve-meter"><span class="reserve-meter-fill ${g.total>cap?'over':''}" style="width:${Math.min(100,g.total/cap*100)}%"></span></span></span><span class="tag ${g.total>cap?'warn':'soft'}">${g.total>cap?'Acima da referência':'Abaixo da referência'}</span></div>`).join(''):'<div class="empty-inline">Cadastre uma instituição e indique o fundo garantidor para acompanhar a exposição.</div>'}</div><p class="help">Monitoramento aproximado, não confirmação de cobertura. Confirme se a instituição e cada produto são elegíveis, some os saldos externos e considere regras de conglomerado e limites globais. O teto de R$ 1 milhão do FGC em quatro anos não está calculado aqui.</p></article>`}
function debtCompareValues(){const rate=currentCdiAnnual(),months=Number($('#debtMonths')?.value||0),tax=months>24?15:months>12?17.5:months>6?20:22.5,netAnnual=rate===null?null:rate*(1-tax/100),monthly=netAnnual===null?null:Math.pow(1+netAnnual/100,1/12)-1,quote=toCents($('#debtPayoff')?.value),payment=toCents($('#debtPayment')?.value),n=months,cet=Number($('#debtCET')?.value);if(!Number.isSafeInteger(quote)||quote<=0||!Number.isSafeInteger(payment)||payment<=0||!Number.isInteger(n)||n<=0||n>600||monthly===null)return '<p class="help">Preencha os valores da proposta de quitação e das parcelas para comparar.</p>';let pv=0;for(let i=1;i<=n;i++)pv+=payment/Math.pow(1+monthly,i);const diff=pv-quote,rateInfo=Number.isFinite(cet)&&cet>0?` CET informado: ${percent(cet)} a.a., ${cet>netAnnual?'acima':'abaixo'} do CDI líquido de referência.`:'';return `<div class="prediction-grid"><div><span>Parcelas trazidas a valor presente</span><strong>${money(Math.round(pv))}</strong></div><div><span>Quitar hoje</span><strong>${money(quote)}</strong></div><div><span>Diferença estimada</span><strong>${money(Math.abs(Math.round(diff)))}</strong></div></div><div class="comparison-bars"><div><span>Parcelas a valor presente</span><i><b style="width:${Math.min(100,pv/Math.max(pv,quote,1)*100)}%"></b></i></div><div><span>Quitar hoje</span><i><b class="alt" style="width:${Math.min(100,quote/Math.max(pv,quote,1)*100)}%"></b></i></div></div><p class="help">${diff>0?'A quitação custa menos que o valor presente estimado das parcelas.':'Manter as parcelas custa menos no cenário de rendimento usado.'}${rateInfo} CDI líquido de referência: ${percent(netAnnual)} a.a. Pressupõe parcelas iguais, pagamentos no fim de cada mês e uso do mesmo dinheiro; não inclui multas, descontos, seguros ou tarifas fora dos valores informados.</p>`}
function updateDebtComparison(){const el=$('#debtCompareResult');if(el)el.innerHTML=debtCompareValues()}
function debtCompareCard(){return `<article class="card">${cardTitle('Comparar quitação de dívida com CDB','Uma comparação matemática usando o rendimento líquido do CDI como custo de oportunidade.')}<div class="simulator-fields"><div class="field"><label for="debtPayoff">Valor para quitar hoje (R$)</label><input id="debtPayoff" type="number" min="0.01" step="0.01" inputmode="decimal"></div><div class="field"><label for="debtPayment">Valor de cada parcela restante (R$)</label><input id="debtPayment" type="number" min="0.01" step="0.01" inputmode="decimal"></div><div class="field"><label for="debtMonths">Parcelas restantes</label><input id="debtMonths" type="number" min="1" max="600" step="1"></div><div class="field"><label for="debtCET">CET informado pela instituição (% a.a.)</label><input id="debtCET" type="number" min="0" step="0.01"></div></div><div id="debtCompareResult" aria-live="polite">${debtCompareValues()}</div></article>`}
function inflationGoalCard(){const rate=currentIpcaAnnual(),latest=latestIpca();return `<article class="card">${cardTitle('Metas corrigidas pela inflação','Cenário que mantém o IPCA observado nos últimos 12 meses até a data da meta.')}${miniLine(ipcaState.rates.slice(-12).map(x=>x.value),'Variação mensal do IPCA nos últimos 12 meses',['12 meses atrás','Último mês'])}<div class="prediction-grid"><div><span>IPCA acumulado em 12 meses</span><strong>${rate===null?'Aguardando dados':percent(rate)}</strong></div><div><span>Último mês disponível</span><strong>${latest?latest.date.slice(5,7)+'/'+latest.date.slice(0,4):'—'}</strong></div><div><span>Status da consulta</span><strong>${esc(ipcaState.loading?'Atualizando':ipcaState.error?'Histórico salvo':'Disponível')}</strong></div></div><p class="help">O IPCA passado é usado como cenário, não como previsão. As metas nominais continuam iguais; nos cartões de metas aparece também o valor aproximado necessário no prazo para preservar o poder de compra.</p></article>`}
function planningSettingsCard(){const amount=db.prefs.balanceAnchorCents===null?'':(db.prefs.balanceAnchorCents/100).toFixed(2),date=db.prefs.balanceAnchorDate||'';return `<article class="card settings-card">${cardTitle('Saldo de referência e reserva','Configure os dados de referência usados nas novas estimativas.')}<form id="planningPrefsForm" class="form-grid"><div class="field"><label for="balanceAnchorAmount">Saldo disponível de referência (R$)</label><input id="balanceAnchorAmount" type="number" min="0" step="0.01" value="${amount}" inputmode="decimal"></div><div class="field"><label for="balanceAnchorDate">Data desse saldo</label><input id="balanceAnchorDate" type="date" value="${date}"></div><div class="field full"><label for="emergencyMonths">Meses de despesas desejados na reserva</label><select id="emergencyMonths">${[3,6,9,12].map(n=>`<option value="${n}" ${db.prefs.emergencyMonths===n?'selected':''}>${n} meses</option>`).join('')}</select></div><div class="setting-actions full"><button class="btn primary" type="submit">Salvar referências</button></div></form><p class="settings-note">O saldo e a data são informados por você. A projeção não substitui o saldo real dos seus bancos.</p></article>`}
const totalMonthSaved=()=>sum(month().movements.map(a=>a.amount));
const dateBR=d=>{const [y,m,day]=d.split('-');return `${day}/${m}/${y}`};
const dateTime=d=>new Date(d+'T12:00:00').getTime();
function stat(label,val,sub,i='wallet',cls=''){return `<article class="stat"><div class="name">${icon(i)}${esc(label)}</div><strong>${val}</strong><div class="hint ${cls}">${sub}</div></article>`}
function heading(title,description,action=''){return `<div class="section-heading"><div><h2>${title}</h2><p>${description}</p></div>${action}</div>`}
function cardTitle(title,description,action=''){return `<div class="card-head"><div><h2>${title}</h2><p>${description}</p></div>${action}</div>`}
let sidebarCompact = localStorage.getItem('reserva.sidebarCompact') === 'true';
function syncSidebar() {
  document.body.classList.toggle('sidebar-compact', sidebarCompact);
  const toggle = $('#sidebarToggle');
  
  toggle.setAttribute('aria-expanded', String(!sidebarCompact));
  toggle.setAttribute('aria-label', sidebarCompact ? 'Expandir menu lateral' : 'Recolher menu lateral');
  toggle.title = toggle.getAttribute('aria-label');
}
$('#sidebarToggle').addEventListener('click', () => {
  sidebarCompact = !sidebarCompact;
  try { localStorage.setItem('reserva.sidebarCompact', String(sidebarCompact)); } catch {}
  syncSidebar();
});
function nav(){const asButton=([id,label,ic])=>`<button type="button" class="nav-button ${state.page===id?'selected':''}" data-page="${id}" aria-label="${label}" title="${label}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}<span class="nav-label">${label}</span><span class="nav-short">${id==='transactions'?'Mov.':id==='analysis'?'Insights':label}</span></button>`;const quick=`<button type="button" id="quickAddButton" class="nav-add" aria-label="Registrar" title="Registrar">${icon('plus')}</button>`;const modules=PAGES.filter(([id])=>id!=='settings');$('#mobileNav').innerHTML=[asButton(modules[0]),asButton(modules[1]),quick,...modules.slice(2).filter(([id])=>id!=='investments').map(asButton)].join('');$('#desktopNav').innerHTML=modules.map(asButton).join('')+'<button class="nav-button" type="button" data-register-menu aria-label="Registrar" title="Registrar">'+icon('plus')+'<span class="nav-label">Registrar</span></button>'+PAGES.filter(([id])=>id==='settings').map(asButton).join('');syncSidebar();const settings=$('#headerSettings');settings?.classList.toggle('selected',state.page==='settings');if(state.page==='settings')settings?.setAttribute('aria-current','page');else settings?.removeAttribute('aria-current')}
function miniProgress(val,target){return `<div class="track"><span style="width:${target?Math.max(0,Math.min(100,val/target*100)):0}%"></span></div>`}
function recentTable(records,kind){const rows=records.filter(r=>r.kind===kind).sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${dateBR(r.date)}</td><td><b>${kind==='income'?(r.source==='salary'?'Salário':'Complemento'):esc(r.category)}</b><div class="sub">${esc(r.note||'Sem descrição')}</div></td><td class="money">${money(r.amount)}</td><td class="right"><div class="table-actions"><button class="edit" data-edit-record="${esc(r.id)}" aria-label="Editar lançamento">Editar</button><button class="delete" data-delete-record="${esc(r.id)}" aria-label="Excluir lançamento">Excluir</button></div></td></tr>`).join('');return rows?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>${kind==='income'?'Origem':'Categoria'}</th><th class="right">Valor</th><th class="right">Ação</th></tr></thead><tbody>${rows}</tbody></table></div>`:`<div class="empty"><strong>Nenhum registro neste mês</strong>Adicione ${kind==='income'?'seu salário ou complemento':'suas despesas'} para começar.</div>`}
function horizontalCategories(rows){const cats=new Map();for(const x of rows.filter(r=>r.kind==='expense'))cats.set(x.category,(cats.get(x.category)||0)+x.amount);return [...cats].sort((a,b)=>b[1]-a[1])}
function donutHTML(rows){const cats=horizontalCategories(rows);const total=sum(cats.map(x=>x[1]));if(!total)return '<div class="empty"><strong>Sem despesas registradas</strong>O gráfico aparecerá quando você registrar seus gastos.</div>';let acc=0;const stops=cats.map(([name,amt])=>{const start=acc;acc+=amt/total*100;return `${CAT_COLORS[CATS.indexOf(name)]||'#acbdc0'} ${start}% ${acc}%`}).join(',');return `<div class="donut-row"><div class="donut" style="background:conic-gradient(${stops})"><b><small>Gastos do mês</small>${money(total)}</b></div><div class="legend-list">${cats.slice(0,5).map(([name,amt])=>`<div class="category-item"><span><i class="color" style="background:${CAT_COLORS[CATS.indexOf(name)]}"></i>${esc(name)}</span><strong>${percent(amt/total*100)}</strong></div>`).join('')}</div></div>`}
function yearChart(){const arr=yearly(state.year);const mx=Math.max(1,...arr.flatMap(a=>[a.income,a.expenses,Math.max(0,a.saved)]));const series=[['income','Renda','#3488f5'],['expense','Despesas','#e9a26e'],['saving','Reserva','#7a75e7']];const bars=arr.map((v,i)=>`<div class="chart-month" title="${MONTHS[i]}: renda ${money(v.income)}, despesas ${money(v.expenses)}, guardado ${money(v.saved)}"><div class="chart-bars">${series.map(([cl],ix)=>{const n=[v.income,v.expenses,Math.max(0,v.saved)][ix];return `<i class="${cl}" style="height:${Math.max(1,n/mx*100)}%"></i>`}).join('')}</div><small>${MONTHS[i].slice(0,3)}</small></div>`).join('');return `<div class="chart-wrap" role="img" aria-label="Comparação mensal entre renda, despesas e reserva em ${state.year}">${bars}</div><div class="legend">${series.map(([_,label,color])=>`<span><i class="dot" style="background:${color}"></i>${label}</span>`).join('')}</div>`}
function upcomingBills() {
  const today = isoToday();
  const period = today.slice(0,7);
  const lastDay = new Date(Number(period.slice(0,4)),Number(period.slice(5)),0).getDate();
  const bills = db.recurring.filter(t => !t.paused && t.kind !== 'income' &&
    t.startMonth <= period && (!t.endMonth || t.endMonth >= period) &&
    !db.records.some(r => r.recurringId === t.id && (r.recurringMonth || r.date.slice(0,7)) === period))
    .map(t => ({...t, due: period+'-'+String(Math.min(lastDay,t.day)).padStart(2,'0')}))
    .sort((a,b) => a.due.localeCompare(b.due)).slice(0,5);
  return `<article class="card"><h2>Contas pendentes deste mês</h2>${bills.length ? bills.map(t =>
    `<p>${dateBR(t.due)} · ${esc(t.note || t.category)} · ${money(t.amount)}${t.due<today?' · vencida':''} <button class="btn small" data-edit-recurring="${esc(t.id)}">Editar previsão</button></p>`).join('') : '<p>Sem contas recorrentes pendentes.</p>'}</article>`;
}
function marketBudgetCard(monthData) {
  const budget=db.prefs.marketBudget??70000;
  const spent=sum(monthData.records.filter(r=>r.kind==='expense'&&r.category==='Mercado').map(r=>r.amount));
  const milestone=[100,75,50,25].find(level=>spent*100>=budget*level);
  const warning=milestone>=75;
  const message=spent>budget?'Cota ultrapassada':spent===budget?'Cota atingida':milestone?`Você atingiu ${milestone}% da cota${warning?' · Gasto alto':''}`:'Abaixo de 25% da cota';
  return `<article class="card market-budget ${warning?'market-warning':''}"><h2>Cota de Mercado</h2>
  <p><strong>${message}</strong></p><p>${money(spent)} gastos de ${money(budget)} em ${esc(monthLabel())}.</p>
  <p>${spent>budget?'Acima da cota':'Disponível na cota'}: ${money(Math.abs(budget-spent))}</p>
  <form data-market-budget-form><label class="field">Cota mensal (R$)<input name="budget" type="number" min="0.01" max="100000000" step="0.01" required value="${hideValues?'':(budget/100).toFixed(2)}"></label><button class="btn" type="submit">Salvar cota</button></form></article>`;
}
document.addEventListener('submit',async event=>{
  if(!event.target.matches('[data-market-budget-form]'))return;
  event.preventDefault();
  const budget=toCents(event.target.elements.namedItem('budget').value);
  if(!Number.isSafeInteger(budget)||budget<=0||budget>10000000000)return notify('Informe uma cota mensal válida.');
  if(await mutate(()=>{db.prefs.marketBudget=budget}))notify('Cota mensal de Mercado atualizada.');
});
function homeOverview(m) {
  const period=mkey(state.year,state.month);
  const investments=db.investments;
  const redeemed=m.redeemed;
  const categories=horizontalCategories(m.records).slice(0,3);
  const committed=m.income?(m.income-m.balance)/m.income*100:null;
  const card=(label,value,detail,page,action,filter='')=>`<article class="card overview-card"><h3>${label}</h3><strong>${value}</strong><p>${detail}</p><button class="btn small" data-page="${page}" ${filter?`data-tx-set="${filter}"`:''}>${action}</button></article>`;
  return `<section aria-labelledby="overviewTitle"><h2 id="overviewTitle">Visão geral · ${esc(monthLabel())}</h2><div class="overview-grid">
  ${card('Saldo disponível',money(m.balance),m.balance<0?'As saídas superaram os recursos do mês.':'Após despesas, aportes e resgates.','analysis','Ver resumo')}
  ${card('Renda comprometida',committed===null?'Sem renda registrada':hideValues?'••••':percent(committed),'Parte da renda que já saiu do caixa, descontados os resgates.','analysis','Ver detalhes')}
  ${card('Carteira de investimentos',money(sum(investments.map(x=>x.balance))),investments.length+' aplicação(ões) · último saldo líquido informado','investments','Abrir carteira')}
  ${card('Investido neste mês',money(m.invested+m.deposits),`Carteira: ${money(m.invested)} · Cofrinhos: ${money(m.deposits)}`,'investments','Ver investimentos')}
  ${(redeemed||m.withdrawals)?card('Resgates do mês',money(redeemed+m.withdrawals),`Carteira: ${money(redeemed)} · Cofrinhos: ${money(m.withdrawals)}`,'investments','Ver carteira'):''}
  ${categories.length?card('Principais gastos',money(sum(categories.map(([,amount])=>amount))),categories.map(([name,amount])=>esc(name)+' '+money(amount)).join(' · '),'transactions','Ver despesas','expense'):''}
  </div></section>`;
}

function home(){const m=month(),today=new Date(),isCurrent=state.year===today.getFullYear()&&state.month===today.getMonth(),daysInMonth=new Date(state.year,state.month+1,0).getDate(),daysLeft=isCurrent?Math.max(1,daysInMonth-today.getDate()+1):daysInMonth,daily=m.balance>0?Math.floor(m.balance/daysLeft):0,activeJars=db.jars.filter(j=>!j.archived&&!j.paused),budgetUse=m.income?Math.max(0,Math.min(100,(m.expenses+m.deposits-m.withdrawals+m.invested)/m.income*100)):0,plan=Engines.insights(db,state.year,state.month),topTip=plan.byCat.biggestRise?`${plan.byCat.biggestRise.name} subiu ${percent(plan.byCat.biggestRise.rateChange)} em relação ao mês anterior.`:plan.byCat.items.length?`Reduzir 10% de ${plan.byCat.items[0].name} liberaria ${money(plan.byCat.savingExample)} neste mês.`:'Registre seus lançamentos para receber uma dica útil.';const pending=recurringForMonth().filter(t=>t.kind!=='income'&&!t.paused&&(!t.endMonth||t.endMonth>=mkey(state.year,state.month))&&!db.records.some(r=>r.kind==='expense'&&r.recurringId===t.id&&(r.recurringMonth||r.date.slice(0,7))===mkey(state.year,state.month))).sort((a,b)=>a.day-b.day).slice(0,3);const reserved=m.saved>=m.minimum;const primary=m.balance>=0?money(m.balance):`−${money(Math.abs(m.balance))}`;const primaryLabel=m.balance>=0?'Você ainda pode gastar':'Saídas acima da renda';$('#page-home').innerHTML=`<div class="today-top-grid"><article class="today-card"><div class="today-overline">${isCurrent?'ATÉ O FIM DE '+MONTHS[state.month].toLocaleUpperCase('pt-BR'):'RESUMO DE '+monthLabel().toLocaleUpperCase('pt-BR')}</div><h2>${primaryLabel}</h2><strong class="today-amount ${m.balance<0?'over-budget':''}">${primary}</strong><p>${m.balance>=0?(isCurrent?`${money(daily)} por dia nos próximos ${daysLeft} dias · saldo mensal, sem sobra trazida de outros meses`:'Saldo do mês selecionado.'):`Revise os lançamentos deste mês para entender a diferença.`}</p>${m.income?`<div class="budget-progress"><div class="budget-progress-track"><span style="width:${budgetUse}%;background:${budgetUse>=100?'var(--danger)':budgetUse>=80?'var(--warning)':'var(--primary)'}"></span></div><div class="budget-progress-caption"><span>${percent(budgetUse)} da renda comprometida</span><span>${budgetUse>=100?'Acima do limite':budgetUse>=80?'Atenção ao ritmo':'Dentro do planejado'}</span></div></div>`:`<div class="empty-inline">Adicione uma renda para acompanhar quanto ainda pode gastar.</div>`}</article>${marketBudgetCard(m)}</div>${homeOverview(m)}<div class="today-stats"><button class="today-stat" data-page="transactions" data-tx-set="income"><span class="today-stat-label">${icon('income')}Entrou</span><strong>${money(m.income)}</strong><small>${m.records.filter(x=>x.kind==='income').length} recebimentos</small></button><button class="today-stat" data-page="transactions" data-tx-set="expense"><span class="today-stat-label expense">${icon('expense')}Saiu</span><strong>${money(m.expenses)}</strong><small>${m.records.filter(x=>x.kind==='expense').length} despesas</small></button><div class="today-stat"><span class="today-stat-label">${icon('piggy')}Reserva deste mês</span><strong>${money(m.deposits)}</strong><small>${m.withdrawals?`${money(m.withdrawals)} resgatados · `:''}${m.income?`${percent(m.rate)} da renda${reserved?' · referência atingida':''}`:'10% é uma referência'}</small></div></div>${goalProgressSummary()}<div class="today-lower"><article class="card">${cardTitle('Próximos vencimentos','Contas previstas que ainda não foram lançadas')}${pending.length?`<div class="upcoming-list">${pending.map(t=>`<div class="upcoming-row"><span class="upcoming-day">${String(t.day).padStart(2,'0')}</span><span><b>${esc(t.category)}</b><small>${isCurrent&&t.day<today.getDate()?`<span class="overdue-label">Vencida há ${today.getDate()-t.day} dia(s)</span> · `:''}${esc(t.note||'Conta recorrente')}</small></span><strong>${money(t.amount)}</strong></div>`).join('')}</div>`:`<div class="empty-inline">Sem vencimentos pendentes próximos. Você pode cadastrar uma conta recorrente em Lançamentos.</div>`}</article><article class="card tip-card">${cardTitle('Uma dica para você','Baseada somente nos lançamentos registrados')}<p>${esc(topTip)}</p><button class="text-link" data-page="analysis">Ver insights</button></article></div>`}
function income(){const m=month();$('#page-income').innerHTML=`${heading('Tudo que entra','Duas opções: salário e complemento.',`<button class="btn primary" data-open="income">${icon('plus')}Adicionar renda</button>`)}<div class="stats">${stat('Salário',money(m.salary),'Total recebido no mês','income')}${stat('Complemento',money(m.complement),'Ganhos adicionais','wallet')}${stat('Renda total',money(m.income),'Base para calcular o mínimo de 10%','income')}${stat('Mínimo para guardar',money(m.minimum),'10% da renda total','piggy')}</div><article class="card">${cardTitle('Entradas de '+monthLabel(),'Informe cada recebimento com valor e data.')}${recentTable(m.records,'income')}</article>`}
function expense(){const m=month();const cats=horizontalCategories(m.records);const pending=pendingRecurring();$('#page-expense').innerHTML=`${heading('Tudo que sai','Água, luz, internet, faculdade, cartões, mercado e outros gastos.',`<div class="actions"><button class="btn" id="copyPreviousBtn" title="Reutilizar gastos do mês anterior e ajustar os valores">Copiar mês anterior</button><button class="btn primary" data-open="expense">${icon('plus')}Adicionar despesa</button></div>`)}<div class="stats">${stat('Total de despesas',money(m.expenses),'Registradas no mês','expense')}${stat('Maior categoria',cats[0]?esc(cats[0][0]):'—',cats[0]?money(cats[0][1]):'Sem registros','chart')}${stat('Renda após despesas',money(m.income-m.expenses),'Antes de separar a reserva','wallet',m.income-m.expenses<0?'warn':'')}${stat('Saldo disponível',money(m.balance),'Já considera o que foi guardado','piggy',m.balance<0?'warn':'')}</div><div class="two-col"><article class="card">${cardTitle('Despesas de '+monthLabel(),'Lançamentos do mês, organizados por categoria')}${recentTable(m.records,'expense')}<p class="help">As contas recorrentes só entram nos gastos quando você confirma o lançamento. Não some a fatura do cartão e as mesmas compras duas vezes.</p></article><article class="card">${cardTitle('Categorias','Distribuição dos gastos do mês')}${donutHTML(m.records)}</article></div><article class="card">${cardTitle('Contas recorrentes','Cadastre uma vez e lance manualmente a cada mês.',`<div class="actions"><button class="btn" data-open="recurring">+ Conta recorrente</button><button class="btn primary" id="applyRecurringBtn" ${pending.length?'':'disabled'}>Lançar pendentes (${pending.length})</button></div>`)}${recurringList()}<p class="help">Cada mês é independente. Ao lançar, você pode corrigir o valor real sem alterar o modelo.</p></article>`}
function transactionItems(){const key=mkey(state.year,state.month),rows=db.records.filter(x=>x.date.startsWith(key)).map(x=>({id:x.id,date:x.date,type:x.kind,amount:x.kind==='income'?x.amount:-x.amount,impact:x.kind==='income'?x.amount:-x.amount,title:x.kind==='income'?(x.source==='salary'?'Salário':'Complemento'):x.category,detail:x.note|| (x.kind==='income'?'Renda':'Despesa'),search:[x.kind,x.category,x.source,x.note,x.date]}));const transfers=db.allocations.filter(x=>x.date.startsWith(key)).map(x=>({id:x.id,date:x.date,type:'goals',amount:x.amount,impact:-x.amount,title:db.jars.find(j=>j.id===x.jarId)?.name||'Cofrinho',detail:x.amount>0?'Depósito':'Resgate',search:['meta',x.note,x.date,db.jars.find(j=>j.id===x.jarId)?.name||'']}));return [...rows,...transfers].sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id))}
let transactionLimit=30, transactionQueryKey="";
function renderTransactionList(){const list=$('#transactionList');if(!list)return;let rows=transactionItems();if(state.txFilter!=='all')rows=rows.filter(x=>x.type===state.txFilter);const q=(state.txSearch||'').trim().toLocaleLowerCase('pt-BR');if(q)rows=rows.filter(x=>[x.title,x.detail,x.date,...x.search,String(Math.abs(x.amount)/100),(Math.abs(x.amount)/100).toLocaleString('pt-BR',{minimumFractionDigits:2}),money(Math.abs(x.amount))].join(' ').toLocaleLowerCase('pt-BR').includes(q));const total=rows.reduce((a,x)=>a+(x.impact||0),0);const key=JSON.stringify([state.year,state.month,state.txFilter,q]);
if(key!==transactionQueryKey){transactionQueryKey=key;transactionLimit=30}
const formatter=rows.slice(0,transactionLimit).map(x=>`<article class="transaction-row"><span class="transaction-icon ${x.type}">${icon(x.type==='income'?'income':x.type==='expense'?'expense':'piggy')}</span><div class="transaction-copy"><b>${esc(x.title)}</b><small>${dateBR(x.date)} · ${esc(x.detail)}</small></div><strong class="transaction-amount ${x.amount>=0?'positive':'negative'}">${x.amount>0?'+':'−'}${money(Math.abs(x.amount))}</strong><div class="transaction-actions">${x.type==='goals'?`<button class="btn small negative" data-delete-allocation="${esc(x.id)}" aria-label="Excluir movimentação de ${esc(x.title)} em ${dateBR(x.date)}">Excluir</button>`:`<button class="btn small" data-edit-record="${esc(x.id)}" aria-label="Editar ${esc(x.title)} em ${dateBR(x.date)}">Editar</button><button class="btn small negative" data-delete-record="${esc(x.id)}" aria-label="Excluir ${esc(x.title)} em ${dateBR(x.date)}">Excluir</button>`}</div></article>`).join('');list.innerHTML=formatter?`${formatter}${rows.length>transactionLimit?'<button class="btn" id="moreTransactions">Ver mais</button>':''}<div class="transaction-total" role="status" tabindex="-1">Mostrando ${Math.min(transactionLimit,rows.length)} de ${rows.length} ${rows.length===1?'item':'itens'} · impacto no orçamento ${total<0?'−':''}${money(Math.abs(total))}</div>`:'<div class="empty"><strong>Nenhum lançamento encontrado</strong>Experimente outro filtro ou registre um lançamento.</div>'}
